custom_css:
:root {
  color-scheme: light;
  --sepia-canvas: #d6c19d;
  --sepia-panel: #eadabd;
  --sepia-field: #fff6e4;
  --sepia-hover: #dcc5a1;
  --sepia-line: #7f613f;
  --sepia-muted: #51402d;
  --sepia-accent: #69401f;
  --sepia-header: #d9c29a;
  --sepia-code: #ecdfc7;
  --monoFontFamily: "JetBrainsMono Nerd Font", "JetBrainsMono NF", "JetBrainsMono Nerd Font Mono", "JetBrainsMono NFM", "JetBrains Mono Nerd Font", "JetBrains Mono", ui-monospace, monospace !important;
  --mainFontFamily: "Inter", "Inter Variable", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
  --SmartThemeFastUIBGColor: var(--SmartThemeBlurTintColor) !important;
  --interactable-outline-color: var(--sepia-accent);
  --interactable-outline-color-faint: rgba(121, 80, 44, 0.3);
  --golden: #805320;
  --warning: #a13027;
  --active: #40623d;
  scrollbar-color: #aa8a5e transparent;
}

body {
  color-scheme: light;
  background-color: var(--sepia-canvas);
  font-family: var(--mainFontFamily);
  font-optical-sizing: auto;
}

#bg1,
#bg_custom {
  background-color: var(--sepia-canvas) !important;
  background-image: linear-gradient(115deg, #dfcfae, #cbb38b) !important;
}

::selection {
  color: #3e3025;
  background: #d8bd8e;
}

#top-bar,
#send_form,
.drawer-content,
dialog.popup,
#dialogue_popup,
#options,
#extensionsMenu {
  background-color: var(--SmartThemeBlurTintColor);
  border-color: var(--sepia-line);
  color: var(--SmartThemeBodyColor);
}

#top-bar {
  box-shadow: none;
  border-bottom: 1px solid var(--sepia-line);
}

#top-settings-holder .drawer-icon {
  color: var(--SmartThemeBodyColor);
  text-shadow: none;
  opacity: 1;
  filter: none;
}

#chat {
  background-color: var(--SmartThemeChatTintColor);
  border-inline: 1px solid rgba(106, 78, 44, 0.2);
}

#chat .mes {
  margin: 0;
  padding: 22px 20px;
  border: 0;
  border-bottom: 1px solid rgba(106, 78, 44, 0.2);
  border-radius: 0;
}

#chat .mes[is_user="true"] {
  background-color: var(--SmartThemeUserMesBlurTintColor);
}

#chat .mes[is_user="false"] {
  background-color: var(--SmartThemeBotMesBlurTintColor);
}

#chat .mes.selected {
  outline: 2px solid var(--sepia-accent);
  outline-offset: -2px;
}

#chat .mes_text {
  font-family: var(--mainFontFamily);
  font-size: calc(var(--mainFontSize) * 1.13);
  line-height: 1.7;
  letter-spacing: normal;
  overflow-wrap: break-word;
}

#chat .mes_text p {
  margin-block: 0 0.9em;
}

#chat .mes_text p:last-child {
  margin-bottom: 0;
}

#chat .ch_name {
  color: var(--SmartThemeBodyColor);
  font-family: var(--mainFontFamily);
  font-weight: 650;
}

.timestamp,
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
  color: var(--sepia-muted);
  opacity: 1;
}

#chat .mes_text a {
  color: #70451f;
  text-decoration: underline;
  text-underline-offset: 0.16em;
}

#chat .mes_text blockquote {
  margin-inline: 0;
  padding: 0.3em 0.9em;
  border-left: 3px solid var(--SmartThemeQuoteColor);
  background: rgba(121, 80, 44, 0.06);
}

#chat .mes_reasoning_details {
  margin-block: 10px;
  padding: 6px 10px;
  border: 1px solid var(--sepia-line);
  border-radius: 7px;
  background-color: var(--sepia-panel);
}

#chat .mes_reasoning_header,
#chat .mes_reasoning {
  color: var(--sepia-muted);
  font-family: var(--mainFontFamily);
  line-height: 1.6;
}

#chat .mes_reasoning_header {
  background: var(--sepia-header) !important;
  color: var(--SmartThemeBodyColor) !important;
  border: 1px solid var(--sepia-line);
  box-shadow: none;
  text-shadow: none;
  filter: none;
  opacity: 1;
}

#chat .mes_reasoning_header_title,
#chat .mes_reasoning_header small {
  color: var(--SmartThemeBodyColor) !important;
  opacity: 1;
}

#chat .mes_reasoning_header:hover {
  background: var(--sepia-hover) !important;
}

.text_pole,
textarea,
input[type="text"],
input[type="number"],
input[type="password"],
input[type="search"],
input[type="url"],
input[type="email"],
select,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple,
.select2-dropdown,
.select2-search__field {
  color: var(--SmartThemeBodyColor);
  background-color: var(--sepia-field);
  border: 1px solid var(--sepia-line);
  border-radius: 6px;
  box-shadow: none;
}

textarea,
input[type="text"],
input[type="number"],
input[type="password"],
input[type="search"],
input[type="url"],
input[type="email"],
select,
button {
  font-family: var(--mainFontFamily);
}

select option,
select option:checked,
select option:not(:checked) {
  color: var(--SmartThemeBodyColor) !important;
  background-color: var(--sepia-field) !important;
}

select option[disabled]:not(:checked) {
  color: var(--sepia-muted) !important;
}

.select2-container--default .select2-selection__rendered,
.select2-container--default .select2-selection__choice {
  color: var(--SmartThemeBodyColor);
}

.select2-container--default .select2-selection__choice,
.select2-container--default .select2-results__option[aria-selected="true"] {
  background-color: var(--sepia-panel);
  border-color: var(--sepia-line);
}

.select2-container--default .select2-results__option--highlighted[aria-selected] {
  color: var(--SmartThemeBodyColor);
  background-color: var(--sepia-hover);
}

input::placeholder,
textarea::placeholder,
.text_pole::placeholder {
  color: var(--sepia-muted);
  opacity: 1;
}

.text_pole:focus-visible,
textarea:focus-visible,
input:focus-visible,
select:focus-visible,
button:focus-visible,
.menu_button:focus-visible,
.drawer-icon:focus-visible {
  outline: 2px solid var(--sepia-accent);
  outline-offset: 2px;
}

input[type="range"],
input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--sepia-accent);
}

.menu_button {
  color: var(--SmartThemeBodyColor);
  background-color: var(--sepia-panel);
  border-color: var(--sepia-line);
  border-radius: 6px;
  text-shadow: none;
}

.menu_button:not(.disabled):hover {
  background-color: var(--sepia-hover);
}

.menu_button.disabled,
#completion_prompt_manager .completion_prompt_manager_prompt_disabled {
  color: var(--sepia-muted);
  opacity: 1;
  border-style: dashed;
}

#send_form {
  border-top: 1px solid var(--sepia-line);
  box-shadow: none;
}

#send_textarea {
  color: var(--SmartThemeBodyColor);
  background-color: var(--sepia-field);
  font-family: var(--mainFontFamily);
  font-size: max(16px, var(--mainFontSize));
  line-height: 1.5;
  border: 1px solid var(--sepia-line);
  border-radius: 7px;
  padding: 10px 12px;
}

code,
pre,
.hljs,
#chat .mes_text code,
#chat .mes_text pre,
#chat .mes_text .hljs {
  color: var(--SmartThemeBodyColor);
  background-color: var(--sepia-code);
  font-family: var(--monoFontFamily, ui-monospace, monospace);
  font-size: 0.86em;
  border-radius: 5px;
}

#chat .mes_text pre {
  border: 1px solid var(--sepia-line);
  padding: 12px;
}

#chat .mes_text pre code,
#chat .mes_text pre .hljs {
  font-size: 1em;
  background: transparent;
}

#chat .mes_text .hljs-comment,
#chat .mes_text .hljs-quote {
  color: #6d583f;
}

#chat .mes_text .hljs-keyword,
#chat .mes_text .hljs-selector-tag,
#chat .mes_text .hljs-literal,
#chat .mes_text .hljs-name {
  color: #80442e;
}

#chat .mes_text .hljs-string,
#chat .mes_text .hljs-regexp,
#chat .mes_text .hljs-attr,
#chat .mes_text .hljs-attribute {
  color: #4e6038;
}

#chat .mes_text .hljs-number,
#chat .mes_text .hljs-symbol,
#chat .mes_text .hljs-built_in,
#chat .mes_text .hljs-title {
  color: #79502c;
}

#chat .mes_text table {
  border-collapse: collapse;
  border-color: var(--sepia-line);
}

#chat .mes_text th,
#chat .mes_text td {
  color: var(--SmartThemeBodyColor);
  border: 1px solid var(--sepia-line);
  padding: 0.45em 0.65em;
}

#chat .mes_text th {
  background-color: var(--sepia-panel);
}

::-webkit-scrollbar-thumb {
  background-color: #aa8a5e;
  border: 2px solid var(--SmartThemeChatTintColor);
  border-radius: 12px;
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--sepia-accent);
}

@media (max-width: 600px) {
  #chat .mes {
    padding: 17px 12px;
  }

  #chat .mes_text {
    font-size: calc(var(--mainFontSize) * 1.1);
    line-height: 1.68;
  }

  #send_textarea {
    padding: 9px 10px;
  }
}

#user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
.standoutHeader,
.inline-drawer-header {
  background: var(--sepia-header) !important;
  color: var(--SmartThemeBodyColor) !important;
  border-color: var(--sepia-line) !important;
  text-shadow: none !important;
  box-shadow: none;
  filter: none;
  opacity: 1;
}

.inline-drawer-header:hover {
  background: var(--sepia-hover) !important;
}

.standoutHeader ~ .inline-drawer-content,
.prompt_order > div,
#completion_prompt_manager .completion_prompt_manager_prompt,
.model-card,
.model-card:hover,
.reverse_proxy_warning:not(small) {
  color: var(--SmartThemeBodyColor);
  background: var(--sepia-panel);
  border-color: var(--sepia-line);
}

.range-block-counter input,
.neo-range-input,
.reasoning_edit_textarea,
.edit_textarea,
#user_avatar_block .avatar_upload,
#character_popup_ok,
.mes-code-preview-toggle {
  color: var(--SmartThemeBodyColor) !important;
  background-color: var(--sepia-field) !important;
  border-color: var(--sepia-line) !important;
  text-shadow: none;
}

.mes-code-preview-toggle:hover,
#character_popup_ok:hover {
  background-color: var(--sepia-hover) !important;
}

#chat .mes_button,
#chat .extraMesButtons > div,
#chat .mes_reasoning_actions .mes_button,
#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay,
#chat .mes_timer,
#chat .timestamp {
  color: var(--sepia-muted);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#chat .mes_button:hover,
#chat .extraMesButtons > div:hover,
#chat .swipe_left:hover,
#chat .swipe_right:hover {
  color: var(--SmartThemeBodyColor);
}

input:disabled,
textarea:disabled,
select:disabled,
button:disabled {
  color: var(--sepia-muted);
  -webkit-text-fill-color: var(--sepia-muted);
  background-color: var(--sepia-panel);
  opacity: 1;
}

input:disabled,
textarea:disabled {
  cursor: not-allowed;
}

.tippy-box,
.tippy-content,
.ui-tooltip {
  color: var(--SmartThemeBodyColor);
  background-color: var(--sepia-field);
  border-color: var(--sepia-line);
  text-shadow: none;
}

.tippy-arrow {
  color: var(--sepia-field);
}

.nice-link,
.drawer-content a:not(.menu_button) {
  color: var(--sepia-accent);
  text-decoration: underline;
  text-underline-offset: 0.15em;
  opacity: 1;
}

.mes_reasoning blockquote {
  color: var(--sepia-muted);
  background-color: var(--sepia-code);
  border-left-color: var(--sepia-accent);
}

code, pre, kbd, samp, .monospace, .CodeMirror, .CodeMirror textarea,
.cm-editor .cm-content, .cm-editor .cm-scroller, .cm-tooltip-autocomplete {
  font-family: var(--monoFontFamily) !important;
  font-variant-ligatures: contextual;
}

#chat,
#sheld,
#top-bar,
#send_form,
.drawer-content,
dialog.popup,
.popup,
#dialogue_popup,
#options,
#extensionsMenu,
#chat .mes,
#chat .mes_reasoning_details {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
}
